import re
p='specs/system-speckit/054-weak-model-spec-authoring/007-playbook-catalog-readme-alignment/spec.md'
lines=open(p).read().splitlines()
rows=[]
inside=False
for i,l in enumerate(lines,1):
    if l.startswith('| File Path | Change Type | Description |'):
        inside=True; continue
    if inside:
        if not l.startswith('|'):
            break
        if set(l.replace('|','').replace('-','').strip())==set():
            continue
        cells=[c.strip() for c in l.strip('|').split('|')]
        rows.append((i,cells[0]))
paths=set()
for i,c in rows:
    for m in re.findall(r'`([^`]+)`',c):
        paths.add(m)
print('rows',len(rows))
print('distinct backticked paths',len(paths))
for p in sorted(paths): print(p)
